export interface AvailabilitySlot {
  startsAt: Date;
  endsAt: Date;
  status: 'FREE' | 'BOOKED';
  bookingId?: string;
}

export interface Availability {
  roomId: string;
  from: Date;
  to: Date;
  slots: AvailabilitySlot[];
}

export async function getAvailability(query: AvailabilityQueryInput): Promise<Availability> {
  const from = parseInstant(query.from);
  const to = parseInstant(query.to);
  if (!isBefore(from, to)) {
    throw validationFailed('`from` must be before `to`', { from: query.from, to: query.to });
  }

  const bookings = await repository.findActiveInRange(query.roomId, from, to);

  const slots: AvailabilitySlot[] = [];
  let cursor = from;
  for (const booking of bookings) {
    const start = isBefore(cursor, booking.startsAt) ? booking.startsAt : cursor;
    const end = isBefore(booking.endsAt, to) ? booking.endsAt : to;
    if (isBefore(cursor, start)) {
      slots.push({ startsAt: cursor, endsAt: start, status: 'FREE' });
      cursor = start;
    }
    if (isBefore(cursor, end)) {
      slots.push({ startsAt: cursor, endsAt: end, status: 'BOOKED', bookingId: booking.id });
      cursor = end;
    }
  }
  if (isBefore(cursor, to)) {
    slots.push({ startsAt: cursor, endsAt: to, status: 'FREE' });
  }

  return { roomId: query.roomId, from, to, slots };
}

