import type { Booking } from '@prisma/client';
import { bookingConflict, notFound, validationFailed } from '../../shared/errors.js';
import {
  normalizeLimit,
  normalizeOffset,
  paginated,
  type Page,
} from '../../shared/pagination.js';
import { isBefore, parseInstant } from '../../shared/time.js';
import * as repository from './repository.js';
import { BOOKING_ACTIVE, BOOKING_CANCELLED } from './schema.js';
import type {
  AvailabilityQueryInput,
  CreateBookingInput,
  ListBookingsInput,
  UpdateBookingInput,
} from './schema.js';

export async function createBooking(input: CreateBookingInput): Promise<Booking> {
  const startsAt = parseInstant(input.startsAt);
  const endsAt = parseInstant(input.endsAt);
  if (!isBefore(startsAt, endsAt)) {
    throw validationFailed('`startsAt` must be before `endsAt`', {
      startsAt: input.startsAt,
      endsAt: input.endsAt,
    });
  }

  const conflict = await repository.findOverlapping(input.roomId, startsAt, endsAt);
  if (conflict) {
    throw bookingConflict(conflict.id);
  }

  return repository.create({
    roomId: input.roomId,
    userId: input.userId,
    title: input.title,
    startsAt,
    endsAt,
  });
}

export async function getBooking(id: string): Promise<Booking> {
  const booking = await repository.findById(id);
  if (!booking) {
    throw notFound('Booking');
  }
  return booking;
}

export async function listBookings(query: ListBookingsInput): Promise<Page<Booking>> {
  const limit = normalizeLimit(query.limit);
  const offset = normalizeOffset(query.offset);
  const [data, total] = await repository.list({
    roomId: query.roomId,
    userId: query.userId,
    status: query.status,
    from: query.from ? parseInstant(query.from) : undefined,
    to: query.to ? parseInstant(query.to) : undefined,
    limit,
    offset,
  });
  return paginated(data, total, limit, offset);
}

export async function updateBooking(id: string, input: UpdateBookingInput): Promise<Booking> {
  const existing = await getBooking(id);
  const roomId = input.roomId ?? existing.roomId;
  const startsAt = input.startsAt !== undefined ? parseInstant(input.startsAt) : existing.startsAt;
  const endsAt = input.endsAt !== undefined ? parseInstant(input.endsAt) : existing.endsAt;

  const scheduleChanged =
    input.roomId !== undefined || input.startsAt !== undefined || input.endsAt !== undefined;

  if (scheduleChanged) {
    if (!isBefore(startsAt, endsAt)) {
      throw validationFailed('`startsAt` must be before `endsAt`', {
        startsAt: startsAt.toISOString(),
        endsAt: endsAt.toISOString(),
      });
    }
    if (existing.status === BOOKING_ACTIVE) {
      const conflict = await repository.findOverlapping(roomId, startsAt, endsAt, id);
      if (conflict) {
        throw bookingConflict(conflict.id);
      }
    }
  }

  return repository.update(id, {
    ...(input.roomId !== undefined ? { roomId: input.roomId } : {}),
    ...(input.userId !== undefined ? { userId: input.userId } : {}),
    ...(input.title !== undefined ? { title: input.title } : {}),
    ...(input.startsAt !== undefined ? { startsAt } : {}),
    ...(input.endsAt !== undefined ? { endsAt } : {}),
  });
}

export async function cancelBooking(id: string): Promise<Booking> {
  const booking = await getBooking(id);
  if (booking.status === BOOKING_CANCELLED) {
    return booking;
  }
  return repository.updateStatus(id, BOOKING_CANCELLED);
}

export async function deleteBooking(id: string): Promise<void> {
  await getBooking(id);
  await repository.remove(id);
}

export interface AvailabilitySlot {
  startsAt: Date;
  endsAt: Date;
  status: 'FREE' | 'BOOKED';
  bookingId?: string;
}

export interface Availability {
  roomId: string;
  from: Date;
  to: Date;
  slots: AvailabilitySlot[];
}

export async function getAvailability(query: AvailabilityQueryInput): Promise<Availability> {
  const from = parseInstant(query.from);
  const to = parseInstant(query.to);
  if (!isBefore(from, to)) {
    throw validationFailed('`from` must be before `to`', { from: query.from, to: query.to });
  }

  const bookings = await repository.findActiveInRange(query.roomId, from, to);

  const slots: AvailabilitySlot[] = [];
  let cursor = from;
  for (const booking of bookings) {
    const start = isBefore(cursor, booking.startsAt) ? booking.startsAt : cursor;
    const end = isBefore(booking.endsAt, to) ? booking.endsAt : to;
    if (isBefore(cursor, start)) {
      slots.push({ startsAt: cursor, endsAt: start, status: 'FREE' });
      cursor = start;
    }
    if (isBefore(cursor, end)) {
      slots.push({ startsAt: cursor, endsAt: end, status: 'BOOKED', bookingId: booking.id });
      cursor = end;
    }
  }
  if (isBefore(cursor, to)) {
    slots.push({ startsAt: cursor, endsAt: to, status: 'FREE' });
  }

  return { roomId: query.roomId, from, to, slots };
}

