  it('reports which booking caused the conflict', async () => {
    const first = await book(24, 25);
    const response = await book(24.5, 25.5, 'Overlap');
    expect(response.json().error.details.conflictingBookingId).toBe(first.json().id);
  });

  it('rejects a booking that starts earlier and overlaps into an active booking', async () => {
    await book(24, 25);
    const response = await book(23.5, 24.5, 'Leading overlap');
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects a booking that fully engulfs an active booking', async () => {
    await book(24, 25);
    const response = await book(23, 26, 'Engulfing');
    expect(response.statusCode).toBe(409);
  });

  it('rejects a booking whose endsAt is not after startsAt', async () => {
    const response = await book(25, 24, 'Backwards');
    expect(response.statusCode).toBe(400);
  });

  it('rejects rescheduling a booking into a conflicting slot', async () => {
    await book(24, 25);
    const second = await book(26, 27, 'Movable');
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) },
    });
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('allows rescheduling a booking into a free slot', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { startsAt: inHours(30), endsAt: inHours(31) },
    });
    expect(response.statusCode).toBe(200);
  });

  describe('availability', () => {
    it('reports the whole range as free when there are no bookings', async () => {
      const response = await app.inject({
        method: 'GET',
        url: `/bookings/availability?roomId=${roomId}&from=${inHours(0)}&to=${inHours(10)}`,
      });
      expect(response.statusCode).toBe(200);
      const body = response.json();
      expect(body.slots).toHaveLength(1);
      expect(body.slots[0].status).toBe('FREE');
    });

    it('splits the range into free and booked slots', async () => {
      const created = await book(24, 25);
      const response = await app.inject({
        method: 'GET',
        url: `/bookings/availability?roomId=${roomId}&from=${inHours(23)}&to=${inHours(26)}`,
      });
      const body = response.json();
      expect(body.slots).toHaveLength(3);
      expect(body.slots[0].status).toBe('FREE');
      expect(body.slots[1]).toMatchObject({ status: 'BOOKED', bookingId: created.json().id });
      expect(body.slots[2].status).toBe('FREE');
    });

    it('excludes cancelled bookings from busy slots', async () => {
      const created = await book(24, 25);
      await app.inject({ method: 'POST', url: `/bookings/${created.json().id}/cancel` });
      const response = await app.inject({
        method: 'GET',
        url: `/bookings/availability?roomId=${roomId}&from=${inHours(23)}&to=${inHours(26)}`,
      });
      const body = response.json();
      expect(body.slots).toHaveLength(1);
      expect(body.slots[0].status).toBe('FREE');
    });

    it('rejects a range where `to` is not after `from`', async () => {
      const response = await app.inject({
        method: 'GET',
        url: `/bookings/availability?roomId=${roomId}&from=${inHours(10)}&to=${inHours(5)}`,
      });
      expect(response.statusCode).toBe(400);
    });
  });
});

